Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
Fix synchronization in TS3Api

Should fix the issues introduced in c8156def8cdc0f33f763b3edd9cec79f86c9b390

Here is the root cause:
The bug was likely caused by improper synchronization when managing the connection state and shutdown process in a multi-threaded environment. The original implementation used simple boolean flags for connection status, which are not thread-safe, leading to potential race conditions where multiple threads could simultaneously modify the connection state, resulting in inconsistent behavior and resource leaks during shutdown.

Here is the patch:
 import java.util.concurrent.ExecutorService;
 import java.util.concurrent.Executors;
+import java.util.concurrent.atomic.AtomicBoolean;

 public class TS3Query {
 	private final TS3Config config;

-	private QueryIO io;
+	private final AtomicBoolean connected = new AtomicBoolean(false);
+	private final AtomicBoolean shuttingDown = new AtomicBoolean(false);

-	private volatile boolean connected;
+	private QueryIO io;

 	/**
 	 */
 	public TS3Query(TS3Config config) {
 		this.config = config;
 		this.fileTransferHelper = new FileTransferHelper(config.getHost());
 		this.connectionHandler = config.getReconnectStrategy().create(config.getConnectionHandler());
-		this.connected = false;

 		this.asyncApi = new TS3ApiAsync(this);
 		this.api = new TS3Api(asyncApi);
 	}


 	public synchronized void connect() {
 		if (userThreadPool.isShutdown()) {
 			throw new IllegalStateException("The query has already been shut down");
 		}

 		QueryIO oldIO = io;
 		if (oldIO != null) {
 			oldIO.disconnect();
 		}

 		io = new QueryIO(this, config);
-		connected = true;
+		connected.set(true);

 		try {
 			connectionHandler.onConnect(this);
 		} catch (Exception e) {
 			log.error("ConnectionHandler threw exception in connect handler", e);
 		}
 		io.continueFrom(oldIO);
 	}

 	 */
-	public synchronized void exit() {
-		if (connected) {
+	public void exit() {
+		if (shuttingDown.compareAndSet(false, true)) {
 			// Sending this command will guarantee that all previously sent commands have been processed
 			try {
 				api.quit();
 			} catch (TS3Exception e) {
 				log.warn("Could not send a quit command to terminate the connection", e);
+			} finally {
+				shutDown();
+			}
+		} else {
+			// Only 1 thread shall ever send quit, the rest of the threads wait for the first thread to finish
+			try {
+				synchronized (this) {
+					while (connected.get()) {
+						wait();
+					}
+				}
+			} catch (InterruptedException e) {
+				// Restore interrupt, then bail out
+				Thread.currentThread().interrupt();
 			}
 		}
+	}

+	private synchronized void shutDown() {
 		if (io != null) {
 			io.disconnect();
 		}

-		connected = false;
 		userThreadPool.shutdown();
+		connected.set(false);
+		notifyAll();
 	}

 	 */
 	public boolean isConnected() {
-		return connected;
+		return connected.get();
 	}


 	void fireDisconnect() {
-		connected = false;
+		connected.set(false);

 		submitUserTask("ConnectionHandler disconnect task", new Runnable() {
 			@Override
 			public void run() {
-				try {
-					connectionHandler.onDisconnect(TS3Query.this);
-				} finally {
-					if (!connected) {
-						exit();
-					}
-				}
+				handleDisconnect();
 			}
 		});
 	}
+
+	private synchronized void handleDisconnect() {
+		try {
+			connectionHandler.onDisconnect(this);
+		} finally {
+			if (!connected.get()) {
+				shutDown();
+			}
+		}
+	}
 }
